import{_ as a,o as s,c as r,a5 as t}from"./chunks/framework.DrDMl0tG.js";const u=JSON.parse('{"title":"Server Example: Synchronous Server Update","description":"","frontmatter":{},"headers":[],"relativePath":"sections/examples/server/synchronous_server_update.md","filePath":"sections/examples/server/synchronous_server_update.md"}'),o={name:"sections/examples/server/synchronous_server_update.md"};function n(i,e,c,l,d,p){return s(),r("div",null,[...e[0]||(e[0]=[t(`<h1 id="server-example-synchronous-server-update" tabindex="-1">Server Example: Synchronous Server Update <a class="header-anchor" href="#server-example-synchronous-server-update" aria-label="Permalink to &quot;Server Example: Synchronous Server Update&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Drives <code>RaisimServer</code> from the simulation loop instead of a server thread: the world advances one step, then the server answers one viewer request. This shows how to keep visualization and camera-sensor updates in lockstep with the simulation.</p><h2 id="target" tabindex="-1">Target <a class="header-anchor" href="#target" aria-label="Permalink to &quot;Target&quot;">​</a></h2><p>CMake target: <code>synchronous_server_update</code>. The source is <code>examples/src/server/synchronous_server_update.cpp</code>.</p><h2 id="run" tabindex="-1">Run <a class="header-anchor" href="#run" aria-label="Permalink to &quot;Run&quot;">​</a></h2><p>Start the example, then connect the viewer:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/synchronous_server_update</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Terminal 2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./build-examples/examples/rayrai_tcp_viewer</span></span></code></pre></div><p>On Windows, run <code>synchronous_server_update.exe</code> instead. The example waits for a viewer on port 8080 before it starts simulating.</p><h2 id="details" tabindex="-1">Details <a class="header-anchor" href="#details" aria-label="Permalink to &quot;Details&quot;">​</a></h2><ul><li>Uses <code>setupSocket()</code>, <code>acceptConnection()</code>, <code>waitForMessageFromClient()</code>, <code>processRequests()</code>, and <code>closeConnection()</code> instead of <code>launchServer()</code>.</li><li>Each loop applies the viewer&#39;s drag force with <code>applyInteractionForce()</code>, integrates the world, waits up to 1 s for a viewer request, and processes it. If processing fails, it waits for a new connection.</li><li>Loads a sensored ANYmal and sets its RGB and depth cameras to <code>MeasurementSource::MANUAL</code> so the viewer renders their frames on request.</li></ul>`,11)])])}const v=a(o,[["render",n]]);export{u as __pageData,v as default};
